import (
	"encoding/json"
	"fmt"
	"io"
	"log"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

// BroadcastMsg is sent to this node when we have a new value to broadcast
type BroadcastMsg struct {
	Mid      int         `json:"msg_id"`
	Message  int         `json:"message"`
	Type     string      `json:"type"`
}

// BroadcastOkMsg is the reply - acknowledging that we received the broadcast
type BroadcastOkMsg struct {
	InReplyTo int    `json:"in_reply_to"`
	Type      string `json:"type"`
}

// ReadMsg asks for all values this node has broadcast and acknowledged
type ReadMsg struct {
	Mid   int       `json:"msg_id"`
	Type  string    `json:"type"`
}

// ReadOkMsg replies with all the values
type ReadOkMsg struct {
	InReplyTo     int          `json:"in_reply_to"`
	Messages      []int        `json:"messages"`
	Type          string       `json:"type"`
}

// TopologyMsg tells the node about the cluster topology (which nodes it knows)
type TopologyMsg struct {
	Mid     int         `json:"msg_id"`
	Type    string      `json:"type"`
	Topology map[string][]string `json:"topology"`
}

// TopologyOkMsg replies - no extra data needed for now
type TopologyOkMsg struct {
	InReplyTo     int          `json:"in_reply_to"`
	Type          string       `json:"type"`
}

func main() {
	node, err := maelstrom.NewNode()
	if err != nil {
		log.Fatalf("Failed to create node: %v", err)
	}
	defer node.Close()

	msgChan := node.Start()
	var values map[int]int
	var ack map[int]bool
	values = make(map[int]int)
	ack = make(map[int]bool)

	// Handle init message first - gets node ID and cluster topology info
	for msg := range msgChan {
		switch msgType := msg.Type; msgType {
		case "init":
			initNode(node, &values, &ack)
			continue
		case "broadcast":
			handleBroadcast(msg, node, values, ack)
		case "read":
			handleRead(msg, node, values, ack)
		case "topology":
			handleTopology(msg, node, values, ack)
		default:
			log.Printf("Unknown message type: %s", msgType)
		}
	}

	// Wait for messages to finish
	node.Wait()
}

func initNode(node *maelstrom.Node, values *map[int]int, ack *map[int]bool) {
	// Read the init response - not really needed for single-node cluster
	// but we reply anyway
	msg := node.Reply("init_ok")
	respChan := node.Receive(msg)
	var resp interface{}
	for resp = range respChan {
		if err, ok := resp.(maelstrom.Err); ok {
			log.Printf("%v", err)
		} else if _, ok := resp.(string); ok {
			log.Println(string(resp.([]byte)))
		}
	}
}

func handleBroadcast(msg maelstrom.Message, node *maelstrom.Node, values *map[int]int, ack *map[int]bool) {
	var data BroadcastMsg
	err := json.Unmarshal(msg.Body, &data)
	if err != nil {
		log.Printf("Failed to unmarshal broadcast message: %v", err)
		return
	}

	// Store the value - it hasn't been acknowledged yet
	values[*data.Mid] = data.Message

	// Reply with broadcast_ok
	okMsg := node.Reply(maelstrom.BroadcastOkMsg{
		InReplyTo: data.Mid,
	})
	respChan := node.Receive(okMsg)
	var resp interface{}
	for resp = range respChan {
		if err, ok := resp.(maelstrom.Err); ok {
			log.Printf("%v", err)
		} else if _, ok := resp.(string); ok {
			log.Println(string(resp.([]byte)))
		}
	}
}

func handleRead(msg maelstrom.Message, node *maelstrom.Node, values *map[int]int, ack *map[int]bool) {
	var data ReadMsg
	err := json.Unmarshal(msg.Body, &data)
	if err != nil {
		log.Printf("Failed to unmarshal read message: %v", err)
		return
	}

	// Collect all values that have been acknowledged
	type Value struct {
		Message int
		ID      int
	}
	var msgs []Value
	for id, val := range *values {
		if ack[id] {
			msgs = append(msgs, Value{Message: val, ID: id})
		}
	}

	// Build the response
	response := `{"type":"read_ok","in_reply_to":` + fmt.Sprint(data.Mid) + `"}`
	valuesOut := make(map[int]int)
	for _, m := range msgs {
		valuesOut[m.ID] = m.Message
	}
	jsonData, _ := json.Marshal(valuesOut)
	response += `, "messages": ` + string(jsonData) + `}`

	// Reply
	node.Send(maelstrom.ReadOkMsg{
		InReplyTo:     data.Mid,
		Messages:      []int{},
		Type:          "read_ok",
	}, jsonData)
}

func handleTopology(msg maelstrom.Message, node *maelstrom.Node, values *map[int]int, ack *map[int]bool) {
	var data TopologyMsg
	err := json.Unmarshal(msg.Body, &data)
	if err != nil {
		log.Printf("Failed to unmarshal topology message: %v", err)
		return
	}

	// Reply with the same topology info
	topologyOkMsg := node.Reply(maelstrom.TopologyOkMsg{
		InReplyTo:     data.Mid,
		Type:          "topology_ok",
	})
	respChan := node.Receive(topologyOkMsg)
	var resp interface{}
	for resp = range respChan {
